package de.fit.framework.persistence.dao;
import de.fit.framework.domain.*;import de.fit.framework.persistence.entity.*;import de.fit.framework.persistence.repository.*;import org.springframework.stereotype.Repository;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Repository public class HilfsmittelCaseDao{private final HilfsmittelCaseRepository repo;public HilfsmittelCaseDao(HilfsmittelCaseRepository r){repo=r;}@Transactional public Long save(HilfsmittelCaseData d){var root=new HilfsmittelCaseEntity(d.gender(),d.age(),d.prescribedOn(),d.coPaymentExempt());for(var p:d.positions()){var pe=new PositionEntity(p.number(),p.serviceFrom(),p.serviceTo());for(var t:p.appointments())pe.add(new TerminEntity(t.sequence(),t.startsAt(),t.endsAt(),t.durationMinutes()));root.add(pe);}return repo.save(root).getId();}@Transactional(readOnly=true)public HilfsmittelCaseData read(Long id){var r=repo.findById(id).orElseThrow();var ps=r.getPositions().stream().sorted(Comparator.comparing(PositionEntity::getNumber)).map(p->new PositionData(p.getNumber(),p.getServiceFrom(),p.getServiceTo(),p.getAppointments().stream().sorted(Comparator.comparing(TerminEntity::getSequence)).map(t->new TerminData(t.getSequence(),t.getStartsAt(),t.getEndsAt(),t.getDurationMinutes())).toList())).toList();return new HilfsmittelCaseData(r.getId(),r.getGender(),r.getAge(),r.getPrescribedOn(),r.isCoPaymentExempt(),ps);}}
